**Files:** `internal/ui/containers/model.go` (field), `update.go` (case `shared.TerminalFocusMsg`,
`RefreshTickMsg` branch); `internal/ui/netdiag/ports_model.go` (field `unfocused`, `handleTick`,
`setTerminalFocus(msg) (*PortsModel, tea.Cmd)`), `internal/ui/netdiag/update.go` (forward the message to
`portsModel`). Tests: `internal/ui/containers/focus_test.go`, `internal/ui/netdiag/ports_focus_test.go`.

**Behaviour:**
- containers: `RefreshTickMsg` while unfocused → `tickCmd()` only (timer kept, no
  `fetchContainers`/`fetchMetrics`). `{true,true}` → `tea.Batch(fetchContainers(), fetchMetrics())`, **no**
  `tickCmd` (the chain is still alive: one chain). `{true,false}` / `{false,_}` → flag only, nil Cmd.
- ports: `handleTick` → `if pm.paused || pm.unfocused { return pm, portsTickCmd(pm.refresh) }`.
  `{true,true}` and `!pm.paused` → `fetchPortsCmd(pm.numericAddrs)` once, no tick. The user's `paused`
  token and the status line are not touched (a separate field, not `pm.paused`).

**Tests to write first** (`testutil.FastTimers(t, &refreshInterval)` for containers; `pm.refresh` short
for ports; assert message **types** from `testutil.Msgs`, not daemon results):
1. containers blurred: `RefreshTickMsg` → the batch yields only `RefreshTickMsg`.
2. containers focus-resume: the batch yields `ContainersListMsg` and `ContainerMetricsMsg`, and no
   `RefreshTickMsg`.
3. containers entry `{true,false}` → nil Cmd.
4. ports blurred: `portsTickMsg` → only `portsTickMsg`, no `portsDataMsg`.
5. ports focus-resume → one `portsDataMsg`, no tick; with user pause on → nil Cmd, bar still shows
   `paused`.
6. netdiag routes `TerminalFocusMsg` to the ports model whatever the active tab.

**Done when:** `go test ./internal/ui/containers ./internal/ui/netdiag -count=1` and
`go test ./internal/app -count=1 -run 'Containers|Netdiag|Activity'` green.

package containers

import (
	"fmt"
	"testing"
	"time"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/shared"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// DEVDESK-210 step 4: the refresh chain keeps ticking while the terminal is
// blurred but skips the read; one read happens when the focus comes back.

func msgTypes(msgs []tea.Msg) []string {
	var out []string
	for _, msg := range msgs {
		out = append(out, fmt.Sprintf("%T", msg))
	}
	return out
}

func countOf[T tea.Msg](msgs []tea.Msg) int {
	n := 0
	for _, msg := range msgs {
		if _, ok := msg.(T); ok {
			n++
		}
	}
	return n
}

func TestABlurredTickKeepsTheChainButSkipsTheRead(t *testing.T) {
	t.Setenv("PATH", t.TempDir())
	testutil.FastTimers(t, &refreshInterval)
	m := loadedModel(t)
	m = feed(t, m, shared.TerminalFocusMsg{Focused: false})

	_, cmd := step(t, m, RefreshTickMsg(time.Now()))
	msgs := testutil.Msgs(cmd)

	if countOf[RefreshTickMsg](msgs) != 1 {
		t.Errorf("a blurred tick must re-arm the chain once, got %v", msgTypes(msgs))
	}
	if countOf[ContainersListMsg](msgs) != 0 || countOf[ContainerMetricsMsg](msgs) != 0 {
		t.Errorf("a blurred tick read the daemon: %v", msgTypes(msgs))
	}
}

func TestFocusResumeReadsOnceWithoutANewChain(t *testing.T) {
	t.Setenv("PATH", t.TempDir())
	testutil.FastTimers(t, &refreshInterval)
	m := feed(t, loadedModel(t), shared.TerminalFocusMsg{Focused: false})

	m, cmd := step(t, m, shared.TerminalFocusMsg{Focused: true, Resume: true})
	msgs := testutil.Msgs(cmd)

	if countOf[ContainersListMsg](msgs) != 1 || countOf[ContainerMetricsMsg](msgs) != 1 {
		t.Errorf("resume must read the list and the metrics once, got %v", msgTypes(msgs))
	}
	if countOf[RefreshTickMsg](msgs) != 0 {
		t.Errorf("resume started a second tick chain: %v", msgTypes(msgs))
	}

	// Focused again: the next tick reads as usual.
	_, cmd = step(t, m, RefreshTickMsg(time.Now()))
	msgs = testutil.Msgs(cmd)
	if countOf[ContainersListMsg](msgs) != 1 || countOf[RefreshTickMsg](msgs) != 1 {
		t.Errorf("a focused tick after resume must read and re-arm, got %v", msgTypes(msgs))
	}
}

func TestFocusEdgesWithoutResumeIssueNoCommand(t *testing.T) {
	tests := []struct {
		name string
		msg  shared.TerminalFocusMsg
	}{
		{"entering the screen focused", shared.TerminalFocusMsg{Focused: true}},
		{"blur", shared.TerminalFocusMsg{Focused: false}},
		{"blur with a stray resume", shared.TerminalFocusMsg{Focused: false, Resume: true}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, cmd := step(t, loadedModel(t), tt.msg)
			if cmd != nil {
				t.Errorf("%+v returned a command, want nil", tt.msg)
			}
		})
	}
}
package netdiag

import (
	"fmt"
	"testing"
	"time"

	tea "charm.land/bubbletea/v2"

